"use client";

import { useEffect, useState } from "react";
import { MeterBar } from "@/components/ui/charts";
import { fmtBytes } from "@/components/ui/primitives";
import { MetricsPanel } from "@/components/customer/MetricsPanel";
import { DiskUsageChart } from "@/components/customer/DiskUsageChart";
import { getGamePlayers } from "@/lib/actions-game-control";
import { GameBuildAI } from "./GameBuildAI";
import type { GameHeaderData, PanelTab } from "./types";

/**
 * Overview tab — the at-a-glance surface: identity + status, resource usage,
 * quick actions that jump to the relevant tab, live resource graphs (reusing the
 * VPS MetricsPanel), a connected-player peek, and the in-server "Build with AI"
 * assistant. All numbers come from the truthful server snapshot in `data`; the
 * player peek and graphs load live.
 */

type QuickAction = { label: string; tab: PanelTab; tone: "brand" | "danger" | "slate" };

const QUICK: QuickAction[] = [
  { label: "Restart", tab: "console", tone: "brand" },
  { label: "Stop", tab: "console", tone: "danger" },
  { label: "Console", tab: "console", tone: "slate" },
  { label: "Files", tab: "files", tone: "slate" },
  { label: "Mods", tab: "mods", tone: "slate" },
  { label: "Backups", tab: "backups", tone: "slate" },
];

export function GameOverview({
  serverId,
  gameFamily,
  data,
  onNavigate,
}: {
  serverId: string;
  gameFamily: string;
  data: GameHeaderData;
  onNavigate: (t: PanelTab) => void;
}) {
  const [players, setPlayers] = useState<{ name: string; extra?: string }[] | null>(null);

  useEffect(() => {
    if (!data.running) return;
    let alive = true;
    getGamePlayers(serverId).then((r) => {
      if (alive && r.ok) setPlayers(r.players);
    });
    return () => {
      alive = false;
    };
  }, [serverId, data.running]);

  const memPct = data.mem.maxBytes ? (data.mem.usedBytes / data.mem.maxBytes) * 100 : 0;
  const diskPct = data.disk.maxGB ? (data.disk.usedGB / data.disk.maxGB) * 100 : 0;

  return (
    <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
      {/* Server info */}
      <div className="card lg:col-span-2">
        <h2 className="text-lg font-semibold">Server overview</h2>
        <p className="mt-1 text-sm text-slate-400">Quick overview of your game server and its performance.</p>
        <dl className="mt-5 grid grid-cols-2 gap-x-6 gap-y-5 text-sm sm:grid-cols-4">
          <Field label="Game" value={data.gameLabel} />
          <Field label="Server ID" value={data.serverIdShort} mono />
          <Field label="Node" value={data.node ?? "—"} />
          <Field label="Status" value={data.running ? "Online" : data.status} accent={data.running} />
          <Field label="Uptime" value={data.uptimeLabel} />
          <Field label="Created" value={data.createdLabel} />
          <Field label="Connect" value={data.connect ?? "—"} mono />
          <Field label="Next restart" value={data.nextRestartLabel ?? "Not scheduled"} />
        </dl>

        <div className="mt-6 border-t border-white/[0.06] pt-5">
          <p className="section-label">Quick actions</p>
          <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3">
            {QUICK.map((q) => (
              <button
                key={q.label}
                onClick={() => onNavigate(q.tab)}
                className={`rounded-xl border px-3 py-2.5 text-sm font-medium transition-colors ${
                  q.tone === "brand"
                    ? "border-brand-500/30 bg-brand-500/10 text-brand-200 hover:bg-brand-500/20"
                    : q.tone === "danger"
                      ? "border-red-500/25 bg-red-500/[0.07] text-red-300 hover:bg-red-500/15"
                      : "border-white/[0.07] bg-white/[0.03] text-slate-300 hover:bg-white/[0.06] hover:text-white"
                }`}
              >
                {q.label}
              </button>
            ))}
          </div>
          <p className="mt-2 text-xs text-slate-500">Power actions live in the header and Console tab, always one click away.</p>
        </div>
      </div>

      {/* Resource usage */}
      <div className="card">
        <h2 className="text-lg font-semibold">Resource usage</h2>
        <div className="mt-5 space-y-5 text-sm">
          <Meter label="CPU" head={`${data.cpuPct.toFixed(0)}%`} value={data.cpuPct} max={100} color="#8a70fb" />
          <Meter
            label="Memory"
            head={`${fmtBytes(data.mem.usedBytes)} / ${fmtBytes(data.mem.maxBytes)}`}
            value={memPct}
            max={100}
            color="#3b82f6"
          />
          <Meter
            label="Disk"
            head={data.disk.usedGB > 0 ? `${data.disk.usedGB.toFixed(1)} / ${data.disk.maxGB} GB` : `${data.disk.maxGB} GB capacity`}
            value={diskPct}
            max={100}
            color="#f59e0b"
          />
          <div className="flex justify-between border-t border-white/[0.06] pt-3">
            <span className="text-slate-400">Network</span>
            <span className="font-mono text-xs">
              <span className="text-accent-cyan">↑ {data.net.outMbps != null ? `${data.net.outMbps.toFixed(1)} MB/s` : "—"}</span>{" "}
              <span className="text-brand-300">↓ {data.net.inMbps != null ? `${data.net.inMbps.toFixed(1)} MB/s` : "—"}</span>
            </span>
          </div>
        </div>
      </div>

      {/* Live graphs */}
      <div className="card lg:col-span-2">
        <div className="mb-2 flex items-center justify-between">
          <h2 className="text-lg font-semibold">Live resource graphs</h2>
        </div>
        <MetricsPanel serverId={serverId} />
        <div className="mt-6 border-t border-white/[0.06] pt-5">
          <p className="section-label mb-3">Disk usage</p>
          <DiskUsageChart serverId={serverId} planTotalGB={data.disk.maxGB} available={data.running} />
        </div>
      </div>

      {/* Players peek */}
      <div className="card">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold">Players online</h2>
          <button onClick={() => onNavigate("players")} className="text-xs text-brand-300 hover:text-brand-200">
            View all
          </button>
        </div>
        {!data.running ? (
          <p className="mt-4 text-sm text-slate-500">Server offline.</p>
        ) : players === null ? (
          <p className="mt-4 text-sm text-slate-500">Loading…</p>
        ) : players.length === 0 ? (
          <p className="mt-4 text-sm text-slate-500">No players connected.</p>
        ) : (
          <ul className="mt-4 space-y-2">
            {players.slice(0, 6).map((p) => (
              <li key={p.name} className="flex items-center gap-2.5 text-sm">
                <span className="flex h-7 w-7 items-center justify-center rounded-full bg-gradient-to-br from-brand-500/40 to-accent-blue/30 text-[11px] font-bold text-white">
                  {p.name.slice(0, 2).toUpperCase()}
                </span>
                <span className="font-medium text-slate-200">{p.name}</span>
                {p.extra && <span className="ml-auto text-xs text-slate-500">{p.extra}</span>}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Build with AI */}
      <div className="lg:col-span-3">
        <GameBuildAI serverId={serverId} gameFamily={gameFamily} gameLabel={data.gameLabel} />
      </div>
    </div>
  );
}

function Field({ label, value, mono, accent }: { label: string; value: string; mono?: boolean; accent?: boolean }) {
  return (
    <div>
      <dt className="text-[11px] font-semibold uppercase tracking-[0.12em] text-slate-500">{label}</dt>
      <dd className={`mt-1 truncate ${mono ? "font-mono text-xs" : ""} ${accent ? "text-emerald-400" : "text-slate-200"}`} title={value}>
        {value}
      </dd>
    </div>
  );
}

function Meter({ label, head, value, max, color }: { label: string; head: string; value: number; max: number; color: string }) {
  return (
    <div>
      <div className="mb-1.5 flex justify-between">
        <span className="text-slate-400">{label}</span>
        <span className="font-semibold text-slate-100">{head}</span>
      </div>
      <MeterBar value={value} max={max} color={color} />
    </div>
  );
}

