async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { osTemplate: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/** Is this server's image a managed game family? */
function isGameServer(server: { osTemplate: { family: string } }): boolean {
  return GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
}

